INSERT OR REPLACE INTO "units" VALUES(1230000200,'高达X分裂者','高达X分裂者',4,2,31,0,'10000000000002300','2300','g2300u00200','GX-9900-DV',1,1,1,1,10000,68,916,837,720,4,65800,201,6021,5505,4478,4,80100,241,7330,6702,5447,4,3,3,3,1,3,'将在塞汶堡市战斗中严重受损的「高达X」改装制造出的MS。
因为卫星加农砲已被破坏到难以修复，自由号的技师「奇多‧萨鲁萨米尔」只好翻新库存的废弃零件，打造出足以应付对MS战的战斗力。
主要武装盾式破坏步枪改以镭射机枪取代。另外，含备用在内，装备了两把大型镭射剑。
另一个巨大改动是加装了名为「分裂者」的大型兵器。它两侧装有喷射器，除了作为盾以外，还可依战况改当作推进器。
机体内部更装设19连发镭射砲「口琴砲」，可当作强大火器使用，大幅提升了机体便利性。','{"id": 1230000200, "hp": 10000, "en": 68, "attack": 764, "defense": 837, "mobility": 720, "movement": 4, "max_hp": 72000, "max_en": 216, "max_attack": 5494, "max_defense": 6024, "max_mobility": 4896, "max_movement": 4, "sp_hp": 11125, "sp_en": 76, "sp_attack": 849, "sp_defense": 931, "sp_mobility": 801, "sp_movement": 4, "sp_max_hp": 80100, "sp_max_en": 241, "sp_max_attack": 6112, "sp_max_defense": 6702, "sp_max_mobility": 5447, "sp_max_movement": 4}','{"unit_id": 1230000200, "unit_ssp_initial_release_set_id": 1230000200, "unit_ssp_custom_core_group_id": 1230000200, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 123000020001, "unit_ssp_custom_core_group_id": 1230000200, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 123000020001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 123000020001, "sort_order": 1, "release_function_type_index": 5, "target_id": 123000020001, "weapon_change": {"id": 123000020001, "before_weapon_id": 0, "after_weapon_id": 123000020090, "weapon": {"id": 123000020090, "name": "分裂者（最大功率） SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 123000020090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 150002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 123000020090, "weapon_status": {"id": 123000020090, "range_min": 3, "range_max": 4, "power