INSERT OR REPLACE INTO "units" VALUES(1230003800,'高达DX','高达DX',4,2,31,0,'10000000000002300','2300','g2300u03800','GX-9901-DX',1,1,1,1,9273,68,954,918,721,5,61014,200,6277,6039,4480,5,74275,239,7642,7353,5449,5,3,3,3,1,3,'新地球联邦军在大战之后，以高达X为基础，投入最新锐技术所开发的MS。
本机继承了高达X的设计理念与资料，并完整移植了高达X的驾驶舱，因此没有新人类也能启动「卫星系统」。
此外，具有压倒性攻击力的卫星加农砲也升级为「卫星系统MK-Ⅱ」并增加了砲管等各种改良，成为输出更加强大的「双卫星加农砲」。
借由这项改良，本机只需要接收一次微波便能连续发射双卫星加农砲。
其他的装备也都整体进行强化，获得了大战后最强MS的性能。
要启动本机也需要「G控（G控制器）」，并制作专用的G控，但也可使用同型机体GX-9900的G控。','{"id": 1230003800, "hp": 9273, "en": 68, "attack": 764, "defense": 918, "mobility": 721, "movement": 5, "max_hp": 66764, "max_en": 215, "max_attack": 5501, "max_defense": 6609, "max_mobility": 4898, "max_movement": 5, "sp_hp": 10316, "sp_en": 76, "sp_attack": 850, "sp_defense": 1022, "sp_mobility": 802, "sp_movement": 5, "sp_max_hp": 74275, "sp_max_en": 239, "sp_max_attack": 6120, "sp_max_defense": 7353, "sp_max_mobility": 5449, "sp_max_movement": 5}','{"unit_id": 1230003800, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1230003800, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 123000380001, "unit_ssp_custom_core_group_id": 1230003800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 123000380001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 123000380001, "sort_order": 1, "release_function_type_index": 5, "target_id": 123000380001, "weapon_change": {"id": 123000380001, "before_weapon_id": 0, "after_weapon_id": 123000380090, "weapon": {"id": 123000380090, "name": "DX專用破壞步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 123000380090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 100002, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 123000380090, "weapon_status": {"id": 123000380090, "range_min": 2, "range_max": 5, "power": 