INSERT OR REPLACE INTO "units" VALUES(1230004300,'阿斯塔隆高达隐藏者','阿斯特龙隐藏者高达',4,2,31,0,'10000000000002300','2300','g2300u04300','NRX-0015-HC',1,1,1,1,8808,69,826,959,762,5,57950,213,5429,6309,4490,5,70545,255,6609,7680,5457,5,3,3,3,1,3,'政府重建委员会为了准备跟宇宙革命军作战，而改装了「阿斯特龙高达」的MS。
由旧地球联邦政府高层为中心所组成的政府重建委员会，为了让前次大战联邦军象征的「高达」复活，而进行机体开发。
其中之一的成果就是阿斯特龙高达，本机则继承了特征，并能适应宇宙环境，还提升了战斗能力。
虽然跟原型机一样采用了变形机构，但MA型态的机身和原形机不同，变成更为平滑的流线型。
此外，本机也考量到跟「华沙哥破坏者高达」联手运用，可以从僚机接收微波能源，来使用装备在MA型态上，跟卫星加农砲有同样威力的「卫星长砲」。','{"id": 1230004300, "hp": 8808, "en": 69, "attack": 718, "defense": 959, "mobility": 762, "movement": 5, "max_hp": 63411, "max_en": 229, "max_attack": 5163, "max_defense": 6904, "max_mobility": 4905, "max_movement": 5, "sp_hp": 9798, "sp_en": 76, "sp_attack": 798, "sp_defense": 1067, "sp_mobility": 848, "sp_movement": 5, "sp_max_hp": 70545, "sp_max_en": 255, "sp_max_attack": 5744, "sp_max_defense": 7680, "sp_max_mobility": 5457, "sp_max_movement": 5}','{"unit_id": 1230004300, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1230004300, "unit_ssp_add_status_id": 100008, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100008, "ssp_hp": 252, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 27, "ssp_mobility": 22, "ssp_max_hp": 5035, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 549, "ssp_max_mobility": 435}, "cores": [{"id": 123000430001, "unit_ssp_custom_core_group_id": 1230004300, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 123000430001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 123000430001, "sort_order": 1, "release_function_type_index": 5, "target_id": 123000430001, "weapon_change": {"id": 123000430001, "before_weapon_id": 0, "after_weapon_id": 123000430090, "weapon": {"id": 123000430090, "name": "剪鉗鐳射加農 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 123000430090, "attack_attr": 1, "weapon_attr": 2, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 110006, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 123000430090, "weapon_status": {"id": 123000430090, "range_min": 2, "range_m