INSERT OR REPLACE INTO "units" VALUES(1430000100,'高达·巴巴托斯 第1型态','高达巴巴托司 第1型态',2,2,2,0,'10000000000004300','4300','g4300u00100','ASW-G-08',1,1,1,1,7150,56,704,779,618,5,38181,147,3755,4157,2970,5,70488,254,6933,7675,5447,5,3,1,3,1,2,'铁华团持有的高达骨架型MS。
300年前的「厄祭战争」末期开发的72架高达骨架采用机中的一架，搭载两座亚哈反应炉，同时运作从而获得庞大的输出。
本机在同骨架中具有较突出的高泛用性，还可换装各种兵器，因此能够适应各种环境。
被发现放置在火星的沙漠地带，长年作为CGS基地的动力源。
当受到加拉尔号角袭击时，第三组的少年们将其再次启动，并让三日月‧奥格斯担任驾驶员参加实战。
双肩的装甲已遗失，各部位也严重劣化，虽然无法发挥应有性能，面对敌机MS古尼捷仍展现压倒性力量，之后作为新成立的铁华团主力机亦相当活跃。
再启动时的武装只有附推进器的锤矛。','{"id": 1430000100, "hp": 7150, "en": 56, "attack": 587, "defense": 779, "mobility": 618, "movement": 5, "max_hp": 51480, "max_en": 186, "max_attack": 4221, "max_defense": 5605, "max_mobility": 3978, "max_movement": 5, "sp_hp": 9790, "sp_en": 76, "sp_attack": 803, "sp_defense": 1066, "sp_mobility": 846, "sp_movement": 5, "sp_max_hp": 70488, "sp_max_en": 254, "sp_max_attack": 5779, "sp_max_defense": 7675, "sp_max_mobility": 5447, "sp_max_movement": 5}','{"unit_id": 1430000100, "unit_ssp_initial_release_set_id": 1430000100, "unit_ssp_custom_core_group_id": 1430000100, "unit_ssp_add_status_id": 100008, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100008, "ssp_hp": 252, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 27, "ssp_mobility": 22, "ssp_max_hp": 5035, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 549, "ssp_max_mobility": 435}, "cores": [{"id": 143000010001, "unit_ssp_custom_core_group_id": 1430000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143000010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143000010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143000010001, "weapon_change": {"id": 143000010001, "before_weapon_id": 0, "after_weapon_id": 143000010090, "weapon": {"id": 143000010090, "name": "鎚矛 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143000010090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 260008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143000010090, "weapon_status": {"id": 143000010090, "range_min": 1, "range_max": 2, "power": 4650, "en": 58, "hit_rate": 10