int": 3000, "acquire_item_type_index": 26, "unit_ssp_custom_core_material_set_id": 10000000000004300, "unit_ssp_custom_core_release_function_set_id": 143000231004, "display_icon_type_index": 2, "schedule_id": 9999990001, "release_condition_custom_core_id": 0, "releases": []}, {"id": 143000231005, "unit_ssp_custom_core_group_id": 1430002310, "level": 20, "release_point": 15000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143000231005, "display_icon_type_index": 1, "schedule_id": 9999990001, "release_condition_custom_core_id": 143000231003, "releases": []}], "initial_release": null}','古尼捷‧烈達 (指揮官機/決鬥規格)','scrape',1792952699,'v2026.10.25',1430003101,'["4300"]');
INSERT OR REPLACE INTO "units" VALUES(1430002800,'格雷兹·艾因','古尼捷‧爱因',4,2,2,0,'10000000000004300','4300','g4300u02800','EB-AX2',1,1,1,1,9980,69,912,842,719,5,65668,204,6001,5539,4470,5,79940,243,7306,6742,5436,5,3,1,3,1,2,'加拉尔号角开发的试作MS。
原本是阿赖耶识系统用的实验机，在爱因‧达尔顿身负重伤后，将机体进行改造，并把他作为活体组件安装在机体内投入实战。
对不可能复原的爱因来说，本机体也兼具生命维持装置的功能。
虽是以古尼捷为基础，在透过阿赖耶识系统达到人机一体的过程中，为了能让人脑更容易认知，而将手部及脚部的骨架延长。
最终变成全长超过20m的大型机体，但利用阿赖耶识系统仍可做出敏捷的动作。
武装为专用的大型斧及收纳式的机关砲。
特征的长手长脚前端具有旋转构造，分别能够作为强力的格斗武器「螺旋拳击」及「钻头脚踢」来使用。','{"id": 1430002800, "hp": 9980, "en": 69, "attack": 760, "defense": 842, "mobility": 719, "movement": 5, "max_hp": 71856, "max_en": 219, "max_attack": 5472, "max_defense": 6061, "max_mobility": 4887, "max_movement": 5, "sp_hp": 11103, "sp_en": 77, "sp_attack": 846, "sp_defense": 937, "sp_mobility": 800, "sp_movement": 5, "sp_max_hp": 79940, "sp_max_en": 243, "sp_max_attack": 6088, "sp_max_defense": 6742, "sp_max_mobility": 5436, "sp_max_movement": 5}','{"unit_id": 1430002800, "unit_ssp_initial_release_set_id": 1430002800, "unit_ssp_custom_core_group_id": 1430002800, "unit_ssp_add_status_id": 100007, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100007, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 481, "ssp_max_mobility": 412}, "cores": [{"id": 143000280001, "unit_ssp_custom_core_group_id": 1430002800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143000280001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143000280001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143000280001, "weapon_change": {"id": 143000280001, "before_weapon_id": 0, "after_weapon_id": 143000280090, "weapon": {"id": 143000280090, "name": "專用大型斧 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143000280090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 280016, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143000280090, "weapon_status": {"id": 143000280090, "range_min": 1, "range_max": 2, "power"