INSERT OR REPLACE INTO "units" VALUES(1430007800,'雷金雷兹朱莉娅 (陆战型)','雷金尼捷茱莉亚 (陆战规格)',4,2,2,0,'10000000000004300','4300','g4300u07800','EB-08jjc',1,1,1,1,9124,69,830,918,726,5,60034,203,5460,6036,4510,5,73081,243,6647,7348,5485,5,3,1,3,1,2,'雷金尼捷茱莉亚的地面战斗型。
是在火星与铁华团进行最后决战时使用的地面用型态。
原本虽是重视宇宙空间战斗所开发的机体， 但由于骨架有著优秀泛用性， 只要更换部分零件便能对应地面战斗。
即便在地面上依然保有高超机动性， 并能展开脚部单元，以气垫悬浮高速移动。
为了使用专用的大型剑，将右手换装成一般的雷金尼捷的手臂， 左手则装备了内藏勾锚的新型大型盾牌。','{"id": 1430007800, "hp": 9124, "en": 69, "attack": 754, "defense": 918, "mobility": 726, "movement": 5, "max_hp": 65691, "max_en": 218, "max_attack": 5428, "max_defense": 6605, "max_mobility": 4931, "max_movement": 5, "sp_hp": 10151, "sp_en": 77, "sp_attack": 839, "sp_defense": 1021, "sp_mobility": 807, "sp_movement": 5, "sp_max_hp": 73081, "sp_max_en": 243, "sp_max_attack": 6038, "sp_max_defense": 7348, "sp_max_mobility": 5485, "sp_max_movement": 5}','{"unit_id": 1430007800, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1430007800, "unit_ssp_add_status_id": 100010, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100010, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 16, "ssp_max_attack": 435, "ssp_max_defense": 526, "ssp_max_mobility": 412}, "cores": [{"id": 143000780001, "unit_ssp_custom_core_group_id": 1430007800, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143000780001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143000780001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143000780001, "weapon_change": {"id": 143000780001, "before_weapon_id": 0, "after_weapon_id": 143000780090, "weapon": {"id": 143000780090, "name": "專用大劍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143000780090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250008, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143000780090, "weapon_status": {"id": 143000780090, "range_min": 1, "range_max": 2, "power": 5000, 