INSERT OR REPLACE INTO "units" VALUES(1431000100,'高达·阿斯塔罗特','高达亚斯塔录',3,2,2,0,'10000000043104300','4310','g4310u00100','ASW-G-29',1,1,1,1,9121,60,727,697,671,5,54356,171,4331,4153,3590,5,83488,253,6652,6380,5493,5,3,1,3,1,2,'华伦家持有的高达骨架型MS。
300年前的「厄祭战争」末期开发的72架高达骨架采用机中的一架， 搭载两座亚哈反应炉，同时运作从而获得庞大的输出。
本机在厄祭战争后不知去向，由华伦家在月面的巨大陨石坑底发现， 自那之后便作为华伦家的所有物被代代相传著。
然而华伦家因爆发丑闻而遭到清算，本机也流入黑市， 塔度天普将其买下时，装备和装甲都被拆除，呈现只剩骨架的状态。
之后，由于是以从各种机体收集来的零件进行复原， 形成左右不对称的情况，需利用腰部的推进器裙甲保持重心的平衡。
武装为折叠式的大型近距离兵器「毁灭魔刀」， 以及华伦家专为本机配备的「210mm对物步枪」。','{"id": 1431000100, "hp": 9121, "en": 60, "attack": 633, "defense": 697, "mobility": 671, "movement": 5, "max_hp": 65665, "max_en": 199, "max_attack": 4552, "max_defense": 5018, "max_mobility": 4320, "max_movement": 5, "sp_hp": 11596, "sp_en": 76, "sp_attack": 804, "sp_defense": 887, "sp_mobility": 853, "sp_movement": 5, "sp_max_hp": 83488, "sp_max_en": 253, "sp_max_attack": 5787, "sp_max_defense": 6380, "sp_max_mobility": 5493, "sp_max_movement": 5}','{"unit_id": 1431000100, "unit_ssp_initial_release_set_id": 1431000100, "unit_ssp_custom_core_group_id": 1431000100, "unit_ssp_add_status_id": 100005, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100005, "ssp_hp": 298, "ssp_en": 1, "ssp_attack": 21, "ssp_defense": 23, "ssp_mobility": 22, "ssp_max_hp": 5950, "ssp_max_en": 16, "ssp_max_attack": 412, "ssp_max_defense": 458, "ssp_max_mobility": 435}, "cores": [{"id": 143100010001, "unit_ssp_custom_core_group_id": 1431000100, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100010001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100010001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100010001, "weapon_change": {"id": 143100010001, "before_weapon_id": 0, "after_weapon_id": 143100010090, "weapon": {"id": 143100010090, "name": "210mm對物步槍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100010090, "attack_attr": 1, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 210001, "ex_short_weapon": 0, "is_full_animation": false, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100010090, "weapon_status": {"id": 143100010090, "range_min": 3, "range_max": 5, "p