INSERT OR REPLACE INTO "units" VALUES(1431001310,'高达·阿斯塔罗特原型','高达亚斯塔录原型',4,2,30,0,'10000000043104300','4310','g4310u01300','ASW-G-29',1,1,1,1,10998,75,898,930,881,5,72366,244,5905,6118,4936,5,80084,266,6535,6771,5448,5,3,3,3,1,2,'高达亚斯塔录原本的姿态。
由华伦家所持有时的状态，利用发现当时的技术， 搭配「厄祭战争」时的样貌修复而成。
修复时，刻上华伦家的家纹，象征获得正式持有的认可。
原本是以广域战斗的概念进行开发的机体， 张开肩部的刀盾及尾翼可变形成飞行型态， 能够独自进行长距离移动，并取得在大气圈内长时间滑翔的能力。
此外，采用特殊的能源传导机构， 能向专用装备「γ纳米积层剑」传送亚哈粒子， 使刀身产生「γ纳米积层反应」， 能将接触到的敌方装甲纳米层构造破坏。
但是，亚哈粒子非常难以控制，此项技术目前已失传。','{"id": 1431001310, "hp": 10998, "en": 75, "attack": 748, "defense": 930, "mobility": 881, "movement": 5, "max_hp": 79185, "max_en": 263, "max_attack": 5384, "max_defense": 6695, "max_mobility": 5387, "max_movement": 5, "sp_hp": 11123, "sp_en": 76, "sp_attack": 757, "sp_defense": 941, "sp_mobility": 891, "sp_movement": 5, "sp_max_hp": 80084, "sp_max_en": 266, "sp_max_attack": 5446, "sp_max_defense": 6771, "sp_max_mobility": 5448, "sp_max_movement": 5}','{"unit_id": 1431001310, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1431001310, "unit_ssp_add_status_id": 100006, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100006, "ssp_hp": 286, "ssp_en": 1, "ssp_attack": 19, "ssp_defense": 24, "ssp_mobility": 23, "ssp_max_hp": 5721, "ssp_max_en": 16, "ssp_max_attack": 389, "ssp_max_defense": 481, "ssp_max_mobility": 458}, "cores": [{"id": 143100131001, "unit_ssp_custom_core_group_id": 1431001310, "level": 1, "release_point": 5000, "acquire_item_type_index": 18, "unit_ssp_custom_core_material_set_id": 0, "unit_ssp_custom_core_release_function_set_id": 143100131001, "display_icon_type_index": 1, "schedule_id": 2511209901, "release_condition_custom_core_id": 0, "releases": [{"unit_ssp_custom_core_release_function_set_id": 143100131001, "sort_order": 1, "release_function_type_index": 5, "target_id": 143100131001, "weapon_change": {"id": 143100131001, "before_weapon_id": 0, "after_weapon_id": 143100131090, "weapon": {"id": 143100131090, "name": "γ納米積層劍 SSP", "type": 1, "tension": 0, "work_type": 0, "main_weapon": 143100131090, "attack_attr": 2, "weapon_attr": 1, "weapon_capability": 1, "weapon_level_up_material": 10021, "weapon_effect": 250003, "ex_short_weapon": 0, "is_full_animation": true, "map_weapon_desc": 0, "map_weapon_range": 0, "map_weapon_trait": 0, "WeaponStatusId": 143100131090, "weapon_status": {"id": 143100131090, "range_min": 1, "range_max": 3, "power": 5000, "en": 63, "hit_rate":