INSERT OR REPLACE INTO "units" VALUES(1501003010,'索恩魔灵高达(钢沃尔瓦使用时)','索恩魔灵高达(钢沃尔凡使用时)',4,2,30,0,'10000000000005010','5010','g5010u03000','EDM-GA-02',1,1,1,1,10179,75,1004,1014,793,5,66976,220,6600,6666,4932,5,74120,240,7304,7377,5453,5,3,3,3,1,2,'与乌尔魔灵同样是供「弗德之黎明」使用的高达类型MS。
